#!/usr/bin/env python3
"""
Round 105b (culprits), 28 September 2026. Needs round 104b.

Where the threat is greatest (a daily index from the map's own figures); V-Dem;
Troutwood's companies and Wreckers of the Earth worldwide as the map's own
rows; CFR and Troutwood page rows out; one banking dynasties row with lines and
a timeline button; readable bank and company boxes; every development bank; the
policy rates row reads again.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

DIFF = ''
NOTE = '## Round 105b (28 September)\n\nNeeds round 104b. Tiles patch round105b_tiles.py beside it.\n\n- Where the threat is greatest (new h1 under Selected Layers): threat_overall,\n  threat_destruction, threat_suppression, threat_crime (country rows, linear\n  0 to 1) from tiles threat/index.json, written daily by threat_index.py:\n  percentile ranks of the map\'s own country figures (GOC 2025, IMF subsidies,\n  OWID CO2 and V-Dem, Global Witness, Walk Free), averaged per category and\n  overall. Not an AI\'s opinion; the box lists each figure and rank.\n- V-Dem: nine owidgrapher rows (vdem_*) under Politics as a front.\n- troutwood_companies (colourBy market_cap) under The stock market and\n  wreckers_world (groupColours by industry group) under Destruction > General,\n  both from tiles troutwood_layers.py (reads troutwood/core.json). card:\n  "company".\n- PANEL_REMOVED: cfr_tracker, tableau_zsf (policy_rates and imbalances are the\n  map\'s own), troutwood, site_banking_dynasties_charts.\n- site_banking_dynasties: links (tiles banking/dynasty_links.geojson, 115\n  lines from each family\'s origin to its cities, coloured by era, width by\n  peak wealth; box with dates, wealth, contemporaries, shared cities) and a\n  "Timeline and comparisons" button opening pages/banking_dynasties.html in a\n  window (sitemapLinks, sitemapTimelineButton, openTimelineWindow).\n- CARDS (bank, company) for geojsonlive rows with cfg.card: headline figure,\n  rank, facts in words, links, every field folded. largest_banks and\n  development_banks use card "bank"; development_banks now every development\n  bank in Wikidata (tiles largest_banks.py).\n- colourBy label; "Coloured by" line uses fieldLabel.\n- getJsonOnce reads NaN/Infinity as null (policy_rates said "unexpected\n  token"; tiles trackers.py no longer writes NaN).\n- school_culprits: five new groups and colours for the 25 entries added from\n  the Suppression page\'s list.\n- Script version app.js?v=996.\n\n'
HEAD = "## Round 105b (28 September)"


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round105b: run from the culprits repository root")
    text = (root / "HANDOFF.md").read_text(encoding="utf-8")
    if "## Round 104b" not in text:
        sys.exit("round105b: round 104b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round105b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            sys.exit("round105b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round105b: applied")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("## Round 104b")
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
